85-        return holidays.findBySheetIdOrderByDateAsc(sheetId).stream().map(Holiday::getDate)
86-                .collect(Collectors.toSet());
87-    }
88-
89-    /** The terms-th day after the date that is neither a Saturday, a Sunday nor one of the holidays. */
90-    public static LocalDate businessDaysAfter(LocalDate date, int terms, Set<LocalDate> holidays) {
91-        LocalDate day = date;
92-        for (int counted = 0; counted < terms;) {
93-            day = day.plusDays(1);
